#!/bin/sh
# Companion V3 batch B (quick graph fixes). Idempotent.
# Generated by backend/database/fix_companion_v3b.py --emit-sh. Run INSIDE the falkordb container:
#   sh /var/lib/falkordb/data/fix_companion_v3b.sh <password>
PASS="$1"
if [ -z "$PASS" ]; then echo "Usage: sh fix_companion_v3b.sh <password>"; exit 1; fi
G="synapse"
run() { redis-cli -a "$PASS" --no-auth-warning GRAPH.QUERY "$G" "$1" > /dev/null 2>&1 && echo "ok" || echo "FAIL: $1"; }

run "MATCH (vf:VariableFeature {id: 'FEAT_FRAME_DEPTH_GDP'}) SET vf.default_value = 100"
run "MATCH (:ProductFamily {id: 'FAM_GDMI'})-[:HAS_VARIABLE_FEATURE]->(f:VariableFeature) WHERE f.parameter_name IS NULL DETACH DELETE f"
run "MATCH (d:Discriminator {id: 'DISC_GDMI_LENGTH'}) WHERE NOT ()-[:SELECTION_DEPENDS_ON]->(d) DETACH DELETE d"
run "MATCH (pf:ProductFamily {id: 'FAM_GDMI_FLEX'}) MERGE (f:VariableFeature {id: 'FEAT_CONNECTION_GDMI_FLEX'}) SET f.parameter_name = 'connection_type', f.name = 'Connection Type', f.default_value = 'PG', f.auto_resolve = true, f.is_variable = true, f.question = 'What duct connection type is needed?', f.applies_to = 'GDMI_FLEX' MERGE (pf)-[:HAS_VARIABLE_FEATURE]->(f) WITH f MATCH (pg:FeatureOption {id: 'OPT_FEAT_CONN_PG'}) MATCH (fl:FeatureOption {id: 'OPT_FEAT_CONN_F'}) MERGE (f)-[:HAS_OPTION]->(pg) MERGE (f)-[:HAS_OPTION]->(fl)"
run "MATCH (pf:ProductFamily) WHERE pf.id IN ['FAM_GDMI', 'FAM_GDMI_FLEX'] SET pf.insulation = 'factory', pf.insulation_note = 'Factory-insulated (double-wall, heat + condensation).'"
run "MATCH (pf:ProductFamily) WHERE pf.id IN ['FAM_GDP', 'FAM_GDB', 'FAM_GDC', 'FAM_GDC_FLEX'] SET pf.insulation = 'on_site', pf.insulation_note = 'Not factory-insulated — the housing is insulated on site by the installer.'"
run "MATCH (pf:ProductFamily) WHERE pf.id IN ['FAM_GDB', 'FAM_GDC', 'FAM_GDMI'] SET pf.code_format = '{family}-{width}x{height}-{length}-{side}-{connection}-{material}'"
run "MATCH (pf:ProductFamily {id: 'FAM_GDP'}) SET pf.code_format = '{family}-{width}x{height}-{frame_depth}-{side}-{connection}-{material}'"
run "MATCH (pf:ProductFamily) WHERE pf.id IN ['FAM_GDB', 'FAM_GDMI', 'FAM_GDP'] SET pf.max_filter_class = 'F9', pf.filter_class_note = 'Rated up to filter class F9 (VVS AMA QGB/1, general ventilation). NOT a certified HEPA installation — if an H13/HEPA element is requested, do not present it as a validated HEPA setup; route to a specialist.'"
run "MATCH (pf:ProductFamily {id: 'FAM_GDMI'}) SET pf.allowed_environments = CASE WHEN 'ENV_OUTDOOR' IN pf.allowed_environments THEN pf.allowed_environments ELSE pf.allowed_environments + 'ENV_OUTDOOR' END"
run "MATCH (pf:ProductFamily {id: 'FAM_EXL'}) SET pf.recommended_for = 'fine filters and higher filter classes (e.g. ePM1 / fine filters)'"
run "MATCH (pf:ProductFamily {id: 'FAM_FILTER_PROFIL'}) SET pf.recommended_for = 'low filter classes only (coarse / ePM10)'"
run "MERGE (a:Accessory {id: 'ACC_FILTER_PROFIL'}) SET a.name = 'Filter Profil', a.full_name = 'Filter Profil (filter rail)', a.category = 'Locking Mechanism', a.applies_to = 'Bag Filter Housings', a.description = 'Filter rail for locking bag/panel filters — recommended for low filter classes.', a.recommended_for = 'low filter classes only (coarse / ePM10)'"
run "MATCH (h:ProductFamily), (a:Accessory {id: 'ACC_FILTER_PROFIL'}) WHERE h.id IN ['FAM_GDB', 'FAM_GDMI', 'FAM_GDP'] MERGE (h)-[:HAS_COMPATIBLE_ACCESSORY]->(a)"
run "MATCH (a:Accessory {id: 'ACC_EXL'}) SET a.recommended_for = 'fine filters and higher filter classes (e.g. ePM1 / fine filters)', a.description = 'Quick-release eccentric locking for bag filter frames — recommended for fine filters and higher filter classes (e.g. ePM1).'"
run "MATCH (pf:ProductFamily {id: 'FAM_FILTER_PROFIL'}) SET pf.corrosion_class = 'C2'"
run "MATCH (v:ProductVariant {id: 'PV_BFF_305x305'}) SET v.weight_kg = 1"
run "MATCH (v:ProductVariant {id: 'PV_BFF_610x305'}) SET v.weight_kg = 1"
run "MATCH (v:ProductVariant {id: 'PV_BFF_910x305'}) SET v.weight_kg = 2"
run "MATCH (v:ProductVariant {id: 'PV_BFF_610x610'}) SET v.weight_kg = 2"
run "MATCH (v:ProductVariant {id: 'PV_BFF_910x610'}) SET v.weight_kg = 3"

echo "--- verify ---"
redis-cli -a "$PASS" --no-auth-warning GRAPH.QUERY "$G" "MATCH (vf:VariableFeature {id: 'FEAT_FRAME_DEPTH_GDP'}) RETURN vf.id, vf.default_value"
redis-cli -a "$PASS" --no-auth-warning GRAPH.QUERY "$G" "MATCH (:ProductFamily {id: 'FAM_GDMI'})-[:HAS_VARIABLE_FEATURE]->(f:VariableFeature) WHERE f.parameter_name = 'housing_length' OR f.parameter_name IS NULL RETURN f.id, f.parameter_name"
redis-cli -a "$PASS" --no-auth-warning GRAPH.QUERY "$G" "MATCH (d:Discriminator {id: 'DISC_GDMI_LENGTH'}) RETURN count(d) AS orphan_discriminators"
redis-cli -a "$PASS" --no-auth-warning GRAPH.QUERY "$G" "MATCH (:ProductFamily {id: 'FAM_GDMI_FLEX'})-[:HAS_VARIABLE_FEATURE]->(f:VariableFeature {parameter_name: 'connection_type'})-[:HAS_OPTION]->(o:FeatureOption) RETURN f.id, collect(o.value), collect(o.length_offset_mm)"
redis-cli -a "$PASS" --no-auth-warning GRAPH.QUERY "$G" "MATCH (pf:ProductFamily) WHERE pf.insulation IS NOT NULL RETURN pf.id, pf.insulation ORDER BY pf.id"
echo "Companion V3 batch B applied. Run SAVE next to persist."
